import { useState } from 'react';

export default function App() {
  const [tugas, setTugas] = useState([]);
  const [teks, setTeks] = useState('');
  function kirim(e) {
    e.preventDefault();
    if (teks.trim() === '') return;
    setTugas([...tugas, { id: crypto.randomUUID(), teks: teks.trim() }]);
    setTeks('');
  }
  return (
    <form onSubmit={kirim}>
      <input value={teks} onChange={(e) => setTeks(e.target.value)} />
      <ul>{tugas.map((t) => <li key={t.id}>{t.teks}</li>)}</ul>
      <p>{tugas.length} tugas</p>
    </form>
  );
}

